      for (const key of ["Enter", " "]) {
        const event = new dom.window.KeyboardEvent("keydown", {
          key,
          bubbles: true,
          cancelable: true,
        });
        chip.dispatchEvent(event);
        expect(event.defaultPrevented).toBe(true);
