import { PERSONAS } from "./personas";

const PORTRAIT_IDS = ["devil", "angel", "scholar", "editor", "reader"] as const;
export type PersonaPortraitId = (typeof PORTRAIT_IDS)[number];

export interface PersonaPortraitIdentity {
  personaId?: string | null;
  name?: string | null;
  role?: string | null;
  /** A custom persona's colour; residents always wear their own. */
  color?: string | null;
  /** A custom editor's uploaded portrait; residents keep their engravings. */
  imageUrl?: string | null;
}

/**
 * Where each engraving's face sits, as fractions of the 480×600 source:
 * the face centre (`fx`, `fy`) frames the medallion, and the lip line
 * (`mx`, `my`, `mw` wide, tilted `tilt` degrees) is where the jaw hinges
 * when the editor speaks. Measured by eye against a 5px grid.
 */
export interface PortraitFocus {
  fx: number;
  fy: number;
  mx: number;
  my: number;
  mw: number;
  tilt: number;
}

const FOCUS: Record<PersonaPortraitId, PortraitFocus> = {
  devil: { fx: 0.406, fy: 0.25, mx: 0.427, my: 0.342, mw: 0.083, tilt: -14 },
  angel: { fx: 0.54, fy: 0.29, mx: 0.585, my: 0.352, mw: 0.098, tilt: -15 },
  scholar: { fx: 0.52, fy: 0.28, mx: 0.527, my: 0.348, mw: 0.075, tilt: -8 },
  editor: { fx: 0.53, fy: 0.25, mx: 0.5, my: 0.352, mw: 0.083, tilt: 12 },
  reader: { fx: 0.55, fy: 0.29, mx: 0.5, my: 0.342, mw: 0.088, tilt: 18 },
};

/** An explicit unknown ID must never borrow a resident's face by name. */
export function resolvePersonaPortrait(input: PersonaPortraitIdentity) {
  const hasId = input.personaId != null;
  const resident = hasId
    ? PERSONAS.find((persona) => persona.id === input.personaId)
    : PERSONAS.find((persona) => persona.name === input.name);
  const portraitId = PORTRAIT_IDS.find((id) => id === resident?.id);
  const color =
    (portraitId ? resident?.color : input.color?.trim()) ||
    "var(--color-ink-light)";
  const name = input.name?.trim() || resident?.name || "Unnamed persona";
  const role = input.role?.trim() || resident?.role || "Editorial voice";
  const words = name.match(/[\p{L}\p{N}]+/gu) ?? [];
  const initials = words
    .slice(0, 2)
    .map((word) => Array.from(word)[0])
    .join("")
    .toLocaleUpperCase();

  return {
    name,
    role,
    initials: initials || "?",
    color,
    portraitId,
    focus: portraitId ? FOCUS[portraitId] : undefined,
    src: portraitId
      ? `/assets/manual/editors/${portraitId}-transparent-480.webp`
      : input.imageUrl || undefined,
    attribution: portraitId ? (hasId ? "id" : "exact-name") : "initials",
  } as const;
}
import { Mark, type Editor } from "@tiptap/core";

export interface PersonaNoteMarkOptions {
  HTMLAttributes: Record<string, any>;
}

export interface PersonaNoteAttributes {
  id: string;
  author: string;
  color: string;
  label: string;
  note: string;
  /** The passage the note is pinned to — rendered as a preview in the popover. */
  quote?: string;
  /** Brief title captured at convene time. */
  briefTitle?: string;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    personaNote: {
      setPersonaNote: (attrs: PersonaNoteAttributes) => ReturnType;
      unsetPersonaNote: () => ReturnType;
    };
  }
}

/**
 * An editor persona's margin note, pinned to the passage it concerns.
 * Stored as a mark so notes travel with the saved folio HTML.
 */
export const PersonaNoteMark = Mark.create<PersonaNoteMarkOptions>({
  name: "personaNote",

  // Several editors may ground conflicting readings in the exact same quote.
  // ProseMirror otherwise treats a second mark of this type as a replacement
  // for the first, which silently removes the earlier note's manuscript anchor.
  excludes: "",

  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },

  addAttributes() {
    const dataAttr = (name: string, fallback = "") => ({
      default: fallback,
      parseHTML: (element: HTMLElement) =>
        element.getAttribute(`data-persona-note-${name}`) ?? fallback,
      renderHTML: (attributes: Record<string, any>) => {
        if (!attributes[name]) return {};
        return { [`data-persona-note-${name}`]: attributes[name] };
      },
    });

    return {
      id: dataAttr("id"),
      author: dataAttr("author"),
      color: dataAttr("color", "var(--color-vermilion)"),
      label: dataAttr("label"),
      note: dataAttr("note"),
      // quote + briefTitle are read back from the DOM by the
      // popover to render a quote preview and a "filed against"
      // line. They were being silently dropped before because the
      // attribute list didn't declare them — setPersonaNote would
      // pass them in and ProseMirror would discard them.
      quote: dataAttr("quote"),
      // The DOM attribute is `data-persona-note-brief` (legacy
      // name from the popover's getAttribute call) while the
      // mark's API name is `briefTitle`. Wire them by hand.
      // The default is `null` (not `""`) so the renderHTML's
      // "is it set?" check doesn't false-negative on an empty
      // string — `dataAttr`'s `if (!attributes[name])` returns
      // `{}` for `""`, which would silently drop every note's
      // briefTitle from the rendered HTML.
      briefTitle: {
        default: null as string | null,
        parseHTML: (element: HTMLElement) =>
          element.getAttribute("data-persona-note-brief"),
        renderHTML: (attributes: Record<string, any>) => {
          if (attributes.briefTitle == null) return {};
          return { "data-persona-note-brief": attributes.briefTitle };
        },
      },
    };
  },

  parseHTML() {
    return [{ tag: "span[data-persona-note-id]" }];
  },

  renderHTML({ HTMLAttributes }) {
    const color =
      HTMLAttributes["data-persona-note-color"] ?? "var(--color-vermilion)";
    return [
      "span",
      {
        ...this.options.HTMLAttributes,
        ...HTMLAttributes,
        class: "twyne-persona-note",
        style: `--note-color: ${color};`,
      },
      0,
    ];
  },

  addCommands() {
    return {
      setPersonaNote:
        (attrs) =>
        ({ chain }) =>
          chain().setMark("personaNote", attrs).run(),
      unsetPersonaNote:
        () =>
        ({ chain }) =>
          chain().unsetMark("personaNote").run(),
    };
  },
});

/** Remove one persona note without disturbing another note on the same quote. */
export function removePersonaNoteMarkById(
  editor: Editor,
  noteId: string,
): boolean {
  const { state, view } = editor;
  const type = state.schema.marks.personaNote;
  if (!type) return false;

  const transaction = state.tr;
  state.doc.descendants((node, pos) => {
    if (!node.isText) return true;
    for (const mark of node.marks) {
      if (mark.type === type && mark.attrs.id === noteId) {
        transaction.removeMark(pos, pos + node.nodeSize, mark);
      }
    }
    return true;
  });
  if (!transaction.docChanged) return false;
  view.dispatch(transaction);
  return true;
}
import { Mark, type Editor } from "@tiptap/core";

export interface CommentMarkOptions {
  HTMLAttributes: Record<string, any>;
}

export interface CommentMarkAttributes {
  id: string;
  author?: string;
  color?: string;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    commentMark: {
      setComment: (attrs: CommentMarkAttributes) => ReturnType;
      unsetComment: () => ReturnType;
    };
  }
}

export const CommentMark = Mark.create<CommentMarkOptions>({
  name: "commentMark",

  // Margin threads are independent even when they quote the same passage.
  // Allow multiple comment marks to coexist instead of letting the newest one
  // replace the first at an identical selection.
  excludes: "",

  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },

  addAttributes() {
    return {
      id: {
        default: null,
        parseHTML: (element) => element.getAttribute("data-comment-id"),
        renderHTML: (attributes) => {
          if (!attributes.id) return {};
          return { "data-comment-id": attributes.id };
        },
      },
      author: {
        default: "You",
        parseHTML: (element) => element.getAttribute("data-comment-author"),
        renderHTML: (attributes) => {
          if (!attributes.author) return {};
          return { "data-comment-author": attributes.author };
        },
      },
      color: {
        default: "var(--color-writer-note)",
        parseHTML: (element) => {
          const color = element.getAttribute("data-comment-color");
          // Migrate comments saved before writer notes received their own
          // semantic color. Mustard belongs to M. Le Stylo.
          return !color || color === "var(--color-mustard)"
            ? "var(--color-writer-note)"
            : color;
        },
        renderHTML: (attributes) => {
          if (!attributes.color) return {};
          return { "data-comment-color": attributes.color };
        },
      },
      resolved: {
        default: false,
        parseHTML: (element) =>
          element.getAttribute("data-comment-resolved") === "true",
        renderHTML: (attributes) =>
          attributes.resolved ? { "data-comment-resolved": "true" } : {},
      },
    };
  },

  parseHTML() {
    return [
      {
        tag: "span[data-comment-id]",
      },
    ];
  },

  renderHTML({ HTMLAttributes }) {
    const color =
      HTMLAttributes["data-comment-color"] ?? "var(--color-writer-note)";
    return [
      "span",
      {
        ...this.options.HTMLAttributes,
        ...HTMLAttributes,
        class: "twyne-comment-mark",
        style:
          HTMLAttributes["data-comment-resolved"] === "true"
            ? "cursor: text;"
            : `background: color-mix(in srgb, ${color} 18%, transparent); border-bottom: 2px solid ${color}; cursor: text;`,
      },
      0,
    ];
  },

  addCommands() {
    return {
      setComment:
        (attrs) =>
        ({ chain }) => {
          return chain()
            .setMark("commentMark", {
              id: attrs.id,
              author: attrs.author ?? "You",
              color: attrs.color ?? "var(--color-writer-note)",
            })
            .run();
        },
      unsetComment:
        () =>
        ({ chain }) => {
          return chain().unsetMark("commentMark").run();
        },
    };
  },
});

/** Keep the anchor for reopening a struck thread, but quiet its annotation. */
export function syncCommentMarkResolution(
  editor: Editor,
  comments: ReadonlyArray<{ id: string; resolved: boolean }>,
): void {
  if (comments.length === 0) return;
  const resolution = new Map(comments.map((c) => [c.id, c.resolved]));
  const { state } = editor;
  const type = state.schema.marks.commentMark;
  if (!type) return;
  const tr = state.tr;
  state.doc.descendants((node, pos) => {
    if (!node.isText) return;
    for (const mark of node.marks) {
      const resolved = resolution.get(mark.attrs.id);
      if (
        mark.type !== type ||
        resolved === undefined ||
        mark.attrs.resolved === resolved
      )
        continue;
      tr.removeMark(pos, pos + node.nodeSize, mark);
      tr.addMark(
        pos,
        pos + node.nodeSize,
        type.create({ ...mark.attrs, resolved }),
      );
    }
  });
  if (tr.docChanged) editor.view.dispatch(tr.setMeta("addToHistory", false));
}

/** Remove one comment id without disturbing another mark on the same quote. */
export function removeCommentMarkById(
  editor: Editor,
  commentId: string,
): boolean {
  const { state, view } = editor;
  const type = state.schema.marks.commentMark;
  if (!type) return false;

  const tr = state.tr;
  state.doc.descendants((node, pos) => {
    if (!node.isText) return true;
    for (const mark of node.marks) {
      if (mark.type === type && mark.attrs.id === commentId) {
        tr.removeMark(pos, pos + node.nodeSize, mark);
      }
    }
    return true;
  });
  if (!tr.docChanged) return false;
  view.dispatch(tr);
  return true;
}

