/*
 * The jaw's opening, 0–1. Registered so the read-aloud keyframes can tween
 * it; Live voice writes it straight from the audio every frame instead.
 */
@property --pp-level {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

.persona-portrait {
  --pp-ring: max(1.5px, calc(var(--persona-portrait-size, 64px) * 0.035));
  position: relative;
  display: block;
  flex: 0 0 var(--persona-portrait-size, 64px);
  width: var(--persona-portrait-size, 64px);
  height: var(--persona-portrait-size, 64px);
  overflow: hidden;
  border-radius: 50%;
  background: radial-gradient(
    circle at 50% 38%,
    color-mix(in srgb, var(--pp-color) 16%, var(--color-paper)) 0 52%,
    color-mix(in srgb, var(--pp-color) 40%, var(--color-paper)) 100%
  );
  box-shadow:
    0 0 0 var(--pp-ring) var(--color-paper),
    0 0 0 calc(var(--pp-ring) * 2 + var(--pp-level) * var(--pp-ring) * 1.6)
      var(--pp-color),
    0 0 calc(var(--pp-level) * var(--persona-portrait-size, 64px) * 0.22)
      calc(var(--pp-ring) * 2)
      color-mix(in srgb, var(--pp-color) 45%, transparent);
  isolation: isolate;
}

.persona-portrait__stage {
  position: absolute;
  width: calc(var(--persona-portrait-size, 64px) * var(--pp-zoom, 2.35));
  aspect-ratio: 4 / 5;
  left: calc(
    50% - var(--persona-portrait-size, 64px) * var(--pp-zoom, 2.35) *
      var(--fx, 0.5)
  );
  top: calc(
    53% - var(--persona-portrait-size, 64px) * var(--pp-zoom, 2.35) * 1.25 *
      var(--fy, 0.3)
  );
  transform-origin: calc(var(--fx, 0.5) * 100%) calc(var(--fy, 0.3) * 100%);
  transition: transform 420ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.persona-portrait img {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  max-width: none;
  height: 100%;
}

/* The dark of an open mouth, under the jaw, hinged on the lip line. */
.persona-portrait__mouth {
  position: absolute;
  left: calc(var(--mx) * 100%);
  top: calc(var(--my) * 100% + 0.15%);
  width: calc(var(--mw) * 62%);
  height: 1.2%;
  border-radius: 50%;
  background: radial-gradient(
    ellipse 50% 60% at 50% 35%,
    #3d1814 0 55%,
    rgb(61 24 20 / 0) 100%
  );
  translate: -50% 0;
  rotate: var(--tilt);
  scale: 1 var(--pp-level);
  transform-origin: 50% 0;
  visibility: hidden;
}

/*
 * The chin: the same engraving, cut along the lip line, feathered at the
 * cheeks and dropped along the head's own tilt. At rest it is pixel-for-pixel
 * the picture beneath, so it only appears while the editor speaks.
 */
.persona-portrait__jaw {
  position: absolute;
  inset: 0;
  background-size: 100% 100%;
  background-repeat: no-repeat;
  clip-path: polygon(0 var(--jaw-y0), 100% var(--jaw-y1), 100% 100%, 0 100%);
  -webkit-mask-image: radial-gradient(
    ellipse calc(var(--mw) * 185%) 9% at calc(var(--mx) * 100%)
      calc(var(--my) * 100% + 3%),
    #000 55%,
    transparent 100%
  );
  mask-image: radial-gradient(
    ellipse calc(var(--mw) * 185%) 9% at calc(var(--mx) * 100%)
      calc(var(--my) * 100% + 3%),
    #000 55%,
    transparent 100%
  );
  transform: rotate(var(--tilt)) translateY(calc(var(--pp-level) * 1.1%))
    rotate(calc(var(--tilt) * -1));
  visibility: hidden;
}

.persona-portrait[data-speaking] .persona-portrait__mouth,
.persona-portrait[data-speaking] .persona-portrait__jaw {
  visibility: visible;
}

/* Read-aloud has no amplitude to follow, so the jaw keeps a speech-like,
   deliberately uneven rhythm: syllables, a stressed beat, a breath. */
.persona-portrait[data-speaking="tts"] {
